import java.util.*;

class Solution {
    public List<List<Integer>> bothCoasts(int[][] heights) {
        int r = heights.length, c = heights[0].length;
        boolean[][] west = new boolean[r][c], east = new boolean[r][c];
        for (int i = 0; i < r; i++) { climb(heights, west, i, 0); climb(heights, east, i, c - 1); }
        for (int j = 0; j < c; j++) { climb(heights, west, 0, j); climb(heights, east, r - 1, j); }
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                if (west[i][j] && east[i][j]) res.add(Arrays.asList(i, j));
        return res;
    }

    // mark every cell reachable from (i, j) by moving to equal-or-higher neighbours
    private void climb(int[][] h, boolean[][] seen, int i, int j) {
        if (seen[i][j]) return;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        seen[i][j] = true;
        stack.push(new int[]{i, j});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            for (int[] d : dirs) {
                int x = cur[0] + d[0], y = cur[1] + d[1];
                if (x >= 0 && y >= 0 && x < h.length && y < h[0].length && !seen[x][y]
                        && h[x][y] >= h[cur[0]][cur[1]]) { // uphill = water could flow back down
                    seen[x][y] = true;
                    stack.push(new int[]{x, y});
                }
            }
        }
    }
}

