class Solution:
    def bothCoasts(self, heights: List[List[int]]) -> List[List[int]]:
        r, c = len(heights), len(heights[0])
        def reach(starts):
            seen = set(starts); st = list(starts)
            while st:
                i, j = st.pop()
                for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                    if 0 <= x < r and 0 <= y < c and (x, y) not in seen and heights[x][y] >= heights[i][j]:
                        seen.add((x, y)); st.append((x, y))
            return seen
        w = reach([(0, j) for j in range(c)] + [(i, 0) for i in range(r)])
        e = reach([(r-1, j) for j in range(c)] + [(i, c-1) for i in range(r)])
        return [[i, j] for i, j in w & e]

