function bothCoasts(heights) {
  const r = heights.length, c = heights[0].length;
  const reach = starts => { const s = heights.map(x => x.map(() => false)), st = [];
    for (const [i, j] of starts) if (!s[i][j]) { s[i][j] = true; st.push([i, j]); }
    while (st.length) { const [i, j] = st.pop();
      for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]]) if (x >= 0 && x < r && y >= 0 && y < c && !s[x][y] && heights[x][y] >= heights[i][j]) { s[x][y] = true; st.push([x, y]); } }
    return s; };
  const ws = [], es = [];
  for (let j = 0; j < c; j++) { ws.push([0, j]); es.push([r-1, j]); }
  for (let i = 0; i < r; i++) { ws.push([i, 0]); es.push([i, c-1]); }
  const w = reach(ws), e = reach(es), out = [];
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) if (w[i][j] && e[i][j]) out.push([i, j]);
  return out;
}
